"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["11880"],{60043(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.peso_area_enem.base_legal_obrigatoria","status":422,"titulo":"Base legal \xe9 obrigat\xf3ria"},"descricao":{"codigo":"uniplus.configuracao.peso_area_enem.base_legal_obrigatoria","requisitos":[],"oQueAconteceu":["Toda linha de pesos por \xe1rea do ENEM registra a base legal que fundamenta os pesos, e o campo `baseLegal` veio ausente, vazio ou s\xf3 com espa\xe7os. A base legal acompanha a linha quando um processo seletivo a congela no edital; para os pesos do Anexo I da Resolu\xe7\xe3o n\xba 805/2024/Consepe, da Unifesspa, ela identifica a norma e o anexo de onde os valores sa\xedram.","A recusa vem na lista `errors` da resposta, com `field` igual a `baseLegal`. As demais recusas do corpo v\xeam na mesma resposta, e nada \xe9 gravado. Na atualiza\xe7\xe3o, o corpo \xe9 conferido antes da busca da linha: um `{id}` que n\xe3o existe s\xf3 responde como n\xe3o encontrado quando o corpo \xe9 v\xe1lido."],"comoResolver":["Informe a base legal dos pesos, com at\xe9 500 caracteres, e envie de novo. Na atualiza\xe7\xe3o, o corpo substitui a linha inteira: a base legal vai sempre, mesmo quando s\xf3 os pesos mudam."],"ondeAparece":["Cadastro dos pesos por \xe1rea do ENEM","Atualiza\xe7\xe3o dos pesos por \xe1rea do ENEM"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Peso area enem"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);